'use strict';
const SIDE_KEYS=['designAngle','designY','designWidth','designHeight','designRotation','bgEnable','bgR','bgG','bgB','bgTol','bgSoft','mirror','invert','smoothPasses','text','letterSpacing','letterThickness','customFontFamily','depthMm','relief','uniformDepth','crisp'];
const SIDE_RUNTIME=['image','imageName','sourceLabel','heightmap','hmRows','hmCols','alphaMap','mask'];
let activeDesignSide=0,designSides=[null,null],designLayers=[[],[]],linkedSideSettings=false,nextLayerId=1;
const MAX_LAYERS=12;let selectedFontReady=Promise.resolve();
function emptyDesignSide(index){return {id:'layer-'+nextLayerId++,kind:'image',designAngle:index?180:0,designY:44.5,designWidth:30,designHeight:30,designRotation:0,bgEnable:true,bgR:255,bgG:255,bgB:255,bgTol:40,bgSoft:false,mirror:false,invert:true,smoothPasses:0,text:'',letterSpacing:0,letterThickness:0,customFontFamily:AppState.customFontFamily,depthMm:1,relief:'raised',uniformDepth:true,crisp:true,image:null,imageName:'',sourceLabel:'—',heightmap:null,hmRows:0,hmCols:0,alphaMap:null,mask:null,fontChoice:els.fontChoice.value};}
function captureDesignSide(){const slot=designSides[activeDesignSide]||(designSides[activeDesignSide]=emptyDesignSide(activeDesignSide));for(const key of [...SIDE_KEYS,...SIDE_RUNTIME])slot[key]=AppState[key];slot.fontChoice=els.fontChoice.value;if(slot.image&&!designLayers[activeDesignSide].includes(slot))designLayers[activeDesignSide].push(slot);
 if(linkedSideSettings){const target=designSides[1-activeDesignSide];if(target?.image){for(const key of SIDE_KEYS.filter(k=>!['text','letterSpacing','letterThickness','customFontFamily'].includes(k)))target[key]=slot[key];target.designAngle=((slot.designAngle+360)%360)-180;target.cache=null;}}
 return slot;}
function hasSleeveArtwork(){return !!AppState.image||designLayers.flat().some(s=>s.image);}
function sideRaster(slot,detail){const settings={...AppState,...slot},key=JSON.stringify([detail,...SIDE_KEYS.filter(k=>!k.startsWith('design')&&k!=='text'&&k!=='customFontFamily').map(k=>settings[k])]);if(!slot.cache||slot.cache.image!==slot.image||slot.cache.key!==key){slot.cache={image:slot.image,key,built:buildHeightmapAtDetail(detail,slot.image,settings)};}return slot.cache.built;}
function sleeveDesignOptions(detail=768){captureDesignSide();return designLayers.flat().filter(s=>s.image).map(slot=>{const built=sideRaster(slot,detail);return {designAngle:slot.designAngle,designY:slot.designY,designWidth:slot.designWidth,designHeight:slot.designHeight,designRotation:slot.designRotation,heightmap:built.hm,rows:built.rows,cols:built.cols,maxHeight:slot.depthMm,negative:slot.relief==='carved',sharp:slot.uniformDepth&&slot.crisp};});}
const layerList=document.createElement('div');layerList.id='designLayerList';layerList.setAttribute('aria-label','Designs on selected side');$('editingSideLabel').after(layerList);
const layerActions=document.createElement('div');layerActions.className='layer-actions';layerActions.innerHTML='<button class="btn btn-ghost btn-sm" id="addImageLayer">＋ Image</button><button class="btn btn-ghost btn-sm" id="addTextLayer">T＋ Text</button>';
layerList.after(layerActions);
function syncDesignSides(){
 $('designSidesPanel').hidden=!templateActive();
 for(let i=0;i<2;i++){const count=designLayers[i].filter(s=>s.image).length;const button=$('editSide'+i);button.setAttribute('aria-pressed',String(i===activeDesignSide));button.textContent=(i?'Back':'Front')+' · '+(count?count+' design'+(count===1?'':'s'):'empty');button.disabled=exportBusy;}
 $('copyDesignSide').disabled=!AppState.image||exportBusy;$('copyDesignSide').textContent='Copy selected to '+(activeDesignSide?'front':'back');
 els.depthIn.closest('.big-field').querySelector('.big-field-label').textContent=templateActive()?'Depth · selected design':'Depth';
 $('centerDesign').textContent='Center selected design';$('clearDesign').textContent='Delete selected design';$('linkDesignSettings').checked=linkedSideSettings;$('linkDesignSettings').nextElementSibling.textContent='Link selected front/back designs';$('sideLinkHelp').textContent=linkedSideSettings?'Size, position and finish match between the selected front and back designs. Artwork stays separate.':'Select a design below or click it on the sleeve. Its size, depth, finish and image settings are independent.';
 if(els.letterSpacingIn){els.letterSpacingIn.value=AppState.letterSpacing;els.letterSpacingVal.textContent=String(AppState.letterSpacing);}if(els.letterThicknessIn){els.letterThicknessIn.value=AppState.letterThickness;els.letterThicknessVal.textContent=String(AppState.letterThickness);}if(els.textStretchField)els.textStretchField.style.display=designSides[activeDesignSide]?.kind==='text'?'block':'none';
 $('editingSideLabel').textContent='Editing '+(activeDesignSide?'back':'front')+' · '+(designSides[activeDesignSide]?.kind==='text'?'text':'image');
 layerList.replaceChildren();for(const slot of designLayers[activeDesignSide]){const row=document.createElement('div');row.className='layer-item';const button=document.createElement('button');button.type='button';button.className='layer-row';button.setAttribute('aria-pressed',String(slot===designSides[activeDesignSide]));const name=slot.kind==='text'?(slot.text||'New text'):(slot.sourceLabel||'Image');button.textContent=(slot.kind==='text'?'T  ':'▧  ')+name;button.title=button.textContent;button.disabled=exportBusy;button.onclick=()=>selectDesignLayer(activeDesignSide,slot.id);const remove=document.createElement('button');remove.type='button';remove.className='layer-delete';remove.title='Delete '+name+' (Ctrl+Z to undo)';remove.setAttribute('aria-label','Delete '+name);remove.disabled=exportBusy;remove.innerHTML='<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/></svg>';remove.onclick=()=>deleteDesignLayer(activeDesignSide,slot.id);row.append(button,remove);layerList.appendChild(row);}

}
function loadSelectedSlot(slot){for(const key of [...SIDE_KEYS,...SIDE_RUNTIME])AppState[key]=slot[key];AppState.textRenderId++;builtinSelectionRevision++;builtinSelection=slot.fontChoice?.startsWith('builtin:')||slot.fontChoice==='system'?slot.fontChoice:'';els.fontChoice.value=slot.fontChoice||'system';els.textInput.value=slot.text||'';if(slot.fontChoice?.startsWith('builtin:')||slot.fontChoice==='system')selectedFontReady=chooseBuiltin(slot.fontChoice,false);els.fileName.textContent=slot.sourceLabel;els.fileName.style.display=slot.image?'':'none';if(slot.image){const built=sideRaster(slot,768);AppState.heightmap=built.hm;AppState.hmRows=built.rows;AppState.hmCols=built.cols;AppState.alphaMap=built.alphaMap;AppState.mask=built.mask;}projectStateToUI();drawHeightmapPreview();syncDesignSides();}
function selectDesignLayer(side,id,turnView=false){if(exportBusy)return;captureDesignSide();const pending=!!AppState.rebuildTimer||!!placementTimer;clearTimeout(AppState.rebuildTimer);AppState.rebuildTimer=null;hidePlacementPreview();setTemplateMove(false);activeDesignSide=side;const slot=designLayers[side].find(s=>s.id===id)||designSides[side]||emptyDesignSide(side);designSides[side]=slot;loadSelectedSlot(slot);if(turnView)templateView(side?'back':'front');if(pending)requestTemplatePreview();}
function switchDesignSide(index,turnView=true){selectDesignLayer(index,designSides[index]?.id,turnView);}
function newDesignLayer(kind='image',side=activeDesignSide){captureDesignSide();if(designLayers.flat().length>=MAX_LAYERS){toast('Up to 12 designs per sleeve. Delete a design before adding another.','error');return null;}const slot=emptyDesignSide(side);slot.kind=kind;if(kind==='text'){slot.designWidth=30;slot.designHeight=15;slot.designY=30;}designLayers[side].push(slot);activeDesignSide=side;designSides[side]=slot;loadSelectedSlot(slot);setSettingsOpen(true);return slot;}
function copyDesignToOtherSide(){if(!AppState.image||exportBusy)return;const source=captureDesignSide();if(designLayers.flat().length>=MAX_LAYERS){toast('The sleeve already has 12 designs.','error');return;}const other=1-activeDesignSide,slot={...source,id:'layer-'+nextLayerId++,designAngle:((source.designAngle+360)%360)-180,cache:null};designLayers[other].push(slot);designSides[other]=slot;syncDesignSides();requestTemplatePreview();dirty();}
function serializeSlot(slot){let image=null;if(slot.image){const c=document.createElement('canvas');c.width=slot.image.width;c.height=slot.image.height;c.getContext('2d').drawImage(slot.image,0,0);image=c.toDataURL('image/png');}return {id:slot.id,kind:slot.kind,image,source:(slot.sourceLabel||'Artwork').slice(0,300),fontChoice:slot.fontChoice||'system',settings:Object.fromEntries(SIDE_KEYS.filter(k=>k!=='customFontFamily').map(k=>[k,slot[k]]))};}
function serializeDesignSides(){captureDesignSide();return designSides.map((s,i)=>serializeSlot(s||emptyDesignSide(i)));}
function serializeDesignLayers(){captureDesignSide();return designLayers.map(list=>list.map(serializeSlot));}
function restoreDesignSides(saved,images,index=0){designLayers=[[],[]];designSides=[null,null];activeDesignSide=saved?index:0;if(saved){saved.forEach((data,i)=>{const slot={...emptyDesignSide(i),depthMm:AppState.depthMm,relief:AppState.relief,uniformDepth:AppState.uniformDepth,crisp:AppState.crisp,...data.settings,image:images[i],imageName:data.source,sourceLabel:data.source};designSides[i]=slot;if(slot.image)designLayers[i].push(slot);});loadSelectedSlot(designSides[index]);}else captureDesignSide();syncDesignSides();}
function restoreDesignLayers(saved,images,index,selectedIds){designLayers=saved.map((list,i)=>list.map((data,j)=>({...emptyDesignSide(i),...data.settings,id:data.id,kind:data.kind,fontChoice:data.fontChoice,image:images[i][j],imageName:data.source,sourceLabel:data.source})));activeDesignSide=index;designSides=designLayers.map((list,i)=>list.find(s=>s.id===selectedIds?.[i])||list[0]||emptyDesignSide(i));nextLayerId=Math.max(nextLayerId,...designLayers.flat().map(s=>Number(s.id.replace('layer-',''))+1));loadSelectedSlot(designSides[index]);}
const sidesOriginalSync=syncTemplateUI;syncTemplateUI=function(){sidesOriginalSync();syncDesignSides();};
const sidesOriginalOptions=templateOptions;templateOptions=function(detail=768){const designs=sleeveDesignOptions(detail);return {...sidesOriginalOptions(),designs,sharp:designs.length?designs.some(d=>d.sharp):AppState.uniformDepth&&AppState.crisp};};
const sidesOriginalBlank=renderTemplateBlank;renderTemplateBlank=function(){if(hasSleeveArtwork())requestTemplatePreview();else sidesOriginalBlank();};
function deleteDesignLayer(side,id){if(exportBusy)return;captureDesignSide();const slot=designLayers[side].find(s=>s.id===id);if(!slot)return;if(typeof commitEditHistory==='function')commitEditHistory();designLayers[side]=designLayers[side].filter(s=>s!==slot);if(designSides[side]===slot)designSides[side]=designLayers[side].at(-1)||emptyDesignSide(side);if(side===activeDesignSide)loadSelectedSlot(designSides[side]);else syncDesignSides();requestTemplatePreview();dirty();if(typeof commitEditHistory==='function')commitEditHistory();toast('Design deleted — Ctrl+Z to undo','success');layerList.querySelector('.layer-row[aria-pressed="true"]')?.focus();}
$('clearDesign').onclick=()=>deleteDesignLayer(activeDesignSide,designSides[activeDesignSide]?.id);
$('centerDesign').onclick=()=>{AppState.designAngle=activeDesignSide?180:0;AppState.designY=44.5;AppState.designRotation=0;projectStateToUI();scheduleRebuild();saveSettings();dirty();};
$('editSide0').onclick=()=>switchDesignSide(0);$('editSide1').onclick=()=>switchDesignSide(1);$('copyDesignSide').onclick=copyDesignToOtherSide;
$('linkDesignSettings').onchange=e=>{linkedSideSettings=e.target.checked;captureDesignSide();syncDesignSides();requestTemplatePreview();dirty();};
$('addImageLayer').onclick=()=>els.fileInput.click();
$('addTextLayer').onclick=()=>{if(newDesignLayer('text')){els.textInput.focus();els.textInput.scrollIntoView({block:'nearest'});dirty();}};
// Typing while an image is selected creates text alongside it instead of replacing it.
els.textInput.addEventListener('input',()=>{if(designSides[activeDesignSide]?.kind!=='text'&&els.textInput.value.trim()){const text=els.textInput.value;if(newDesignLayer('text')){AppState.text=text;els.textInput.value=text;els.textInput.focus();}}},true);
const layerOriginalSetImage=setDesignImage;setDesignImage=function(img,label){const keepHeight=designSides[activeDesignSide]?.kind==='text'&&!!AppState.image&&label?.startsWith('text:')?AppState.designHeight:null;layerOriginalSetImage(img,label);if(keepHeight!==null)AppState.designHeight=keepHeight;const slot=captureDesignSide();slot.kind=label?.startsWith('text:')?'text':'image';syncDesignSides();};
const dropChoice=document.createElement('dialog');dropChoice.className='product-dialog';dropChoice.innerHTML='<h2>Add this image?</h2><p>The selected side already has artwork. Add this as another design, or replace only the selected design.</p><div class="layer-actions"><button class="btn btn-primary" data-choice="add">Add design</button><button class="btn btn-ghost" data-choice="replace">Replace selected</button><button class="btn btn-ghost" data-choice="cancel">Cancel</button></div>';document.body.appendChild(dropChoice);
let uploadQueue=Promise.resolve();
function askImageAction(){return new Promise(resolve=>{const finish=value=>{dropChoice.close();resolve(value);};dropChoice.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>finish(b.dataset.choice));dropChoice.oncancel=e=>{e.preventDefault();finish('cancel');};dropChoice.showModal();dropChoice.querySelector('[data-choice="add"]').focus();});}
function receiveSideUpload(img,label,index){uploadQueue=uploadQueue.then(async()=>{captureDesignSide();const target=designSides[index];const action=designLayers[index].some(s=>s.image)?await askImageAction():'add';if(action==='cancel')return;if(action==='add'){if(!newDesignLayer('image',index))return;}else selectDesignLayer(index,target?.id);AppState.bgEnable=true;AppState.text='';els.textInput.value='';setDesignImage(img,label);projectStateToUI();dirty();}).catch(e=>toast(e.message,'error'));return uploadQueue;}
let logoPickStart=null;
function selectLogoAtPointer(e,reveal=true){if(!templateActive()||!templateRayMesh||!camera||exportBusy)return;const rect=renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),camera);const hit=ray.intersectObject(templateRayMesh,false)[0];if(!hit)return;const p=hit.point,n=hit.face.normal,radial=new THREE.Vector3(p.x,0,p.z).normalize();if(n.dot(radial)<.25||Math.abs(n.y)>.78)return;captureDesignSide();const chart=placementMesh?.userData.chart||SleeveTemplate.profile(templateBase),arc=SleeveTemplate.arcAt(chart,Math.atan2(p.z,p.x));let picked=null;
 for(let side=0;side<2;side++)for(const slot of designLayers[side]){if(!slot.image)continue;const map=sideRaster(slot,768),center=SleeveTemplate.arcAt(chart,(slot.designAngle||0)*Math.PI/180+Math.PI/2);let dx=center-arc;dx-=Math.round(dx/chart.perimeter)*chart.perimeter;const dy=p.y-slot.designY,r=slot.designRotation*Math.PI/180,c=Math.cos(r),s=Math.sin(r),u=(dx*c+dy*s)/slot.designWidth+.5,v=.5-(-dx*s+dy*c)/slot.designHeight;if(u>=0&&u<1&&v>=0&&v<1&&map.hm[Math.round(v*(map.rows-1))*map.cols+Math.round(u*(map.cols-1))]>.25)picked={side,slot};}
 if(!picked)return;selectDesignLayer(picked.side,picked.slot.id);if(reveal){setSettingsOpen(true);$('designSidesPanel').scrollIntoView({block:'nearest',behavior:'smooth'});}templateStatus('Editing '+picked.slot.sourceLabel);return true;}
$('threeContainer').addEventListener('pointerdown',e=>{logoPickStart=e.button===0&&!templateMove?{x:e.clientX,y:e.clientY,id:e.pointerId}:null;});$('threeContainer').addEventListener('pointerup',e=>{const start=logoPickStart;logoPickStart=null;if(start&&start.id===e.pointerId&&Math.hypot(e.clientX-start.x,e.clientY-start.y)<5&&!templateMove)selectLogoAtPointer(e);});$('threeContainer').addEventListener('pointercancel',()=>logoPickStart=null);
